<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { all,ApiError,api,messageOf } from '../api'
import type { LanMember } from '../lan'
import { membersChanged,projectMembersRevision } from '../projectMembers'
const props=defineProps<{projectId:string;readonly?:boolean}>(),emit=defineEmits<{changed:[];busy:[value:boolean]}>()
const members=ref<LanMember[]>([]),candidates=ref<LanMember[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),name=ref(''),existing=ref(''),mode=ref('new'),renaming=ref<LanMember>(),renameValue=ref('')
const choices=computed(()=>candidates.value.filter(m=>m.enabled&&!members.value.some(p=>p.id===m.id)))
let request=0
async function load(){const seq=++request;members.value=[];candidates.value=[];error.value='';if(!props.projectId)return;loading.value=true;try{const [list,allMembers]=await Promise.all([all<LanMember>(`/api/projects/${encodeURIComponent(props.projectId)}/members`),all<LanMember>('/api/lan/members')]);if(seq===request){members.value=list;candidates.value=allMembers}}catch(e){if(seq===request)error.value=messageOf(e)}finally{if(seq===request)loading.value=false}}
async function showError(e:unknown){const message=messageOf(e);if(e instanceof ApiError&&e.status===409){const id=renaming.value?.id;await load();if(id)renaming.value=members.value.find(m=>m.id===id);error.value=message+'；名单已刷新，请核对后重试。'}else error.value=message}
async function add(){if(saving.value||props.readonly)return;const chosen=candidates.value.find(m=>m.id===existing.value);if(mode.value==='new'&&!name.value.trim()||mode.value==='existing'&&!chosen)return;saving.value=true;emit('busy',true);error.value='';success.value='';try{await api(`/api/projects/${encodeURIComponent(props.projectId)}/members`,{method:'POST',body:JSON.stringify(mode.value==='new'?{name:name.value.trim()}:{member_id:chosen!.id,version:chosen!.version})});name.value='';existing.value='';success.value='成员已加入项目，可在负责人和人员列表中选择。';membersChanged();emit('changed')}catch(e){await showError(e)}finally{saving.value=false;emit('busy',false)}}
async function remove(member:LanMember){if(saving.value||props.readonly||!window.confirm(`将「${member.name}」移出当前项目？未完成任务需先清空负责人或改派，历史记录保留。`))return;saving.value=true;emit('busy',true);error.value='';success.value='';try{await api(`/api/projects/${encodeURIComponent(props.projectId)}/members/${encodeURIComponent(member.id)}`,{method:'PATCH',body:JSON.stringify({version:member.version,remove:true})});success.value='成员已移出当前项目。';membersChanged();emit('changed')}catch(e){await showError(e)}finally{saving.value=false;emit('busy',false)}}
async function rename(){const member=renaming.value;if(!member||saving.value||props.readonly||!renameValue.value.trim())return;saving.value=true;emit('busy',true);error.value='';success.value='';try{await api(`/api/projects/${encodeURIComponent(props.projectId)}/members/${encodeURIComponent(member.id)}`,{method:'PATCH',body:JSON.stringify({version:member.version,name:renameValue.value.trim()})});renaming.value=undefined;success.value='成员姓名已更新，已有会话需重新配对。';membersChanged();emit('changed')}catch(e){await showError(e)}finally{saving.value=false;emit('busy',false)}}
watch([()=>props.projectId,projectMembersRevision],load,{immediate:true})
defineExpose({load,canLeave:()=>!saving.value&&(!name.value.trim()&&!existing.value&&!renaming.value||window.confirm('成员修改尚未提交，确定关闭？'))})
</script>
<template><section class="project-members"><p class="input-hint">项目内的负责人和人员统一从此名单选择；单机使用也可维护，无需开启局域网协同。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="success" class="member-feedback" role="status">{{success}}</p><p v-if="loading" class="input-hint">正在读取项目成员…</p><ul v-else-if="members.length" class="project-member-list"><li v-for="member in members" :key="member.id"><span><strong>{{member.name}}</strong><small>{{member.id}}<span v-if="!member.enabled"> · 已停用</span></small></span><div v-if="!readonly" class="row-actions"><button type="button" class="text-button" :disabled="saving" @click="renaming=member;renameValue=member.name">修改姓名</button><button type="button" class="text-button" :disabled="saving" @click="remove(member)">移出项目</button></div></li></ul><p v-else class="input-hint">此项目尚无成员，请先新增或加入已有成员。</p><div v-if="renaming&&!readonly" class="member-rename"><label>修改成员姓名<input v-model="renameValue" maxlength="100" :disabled="saving" @keydown.enter.prevent="rename"/></label><p class="input-hint">此成员在所有项目共用此姓名；修改后需重新配对。</p><div class="row-actions"><button type="button" class="button subtle small" :disabled="saving||!renameValue.trim()" @click="rename">保存姓名</button><button type="button" class="text-button" :disabled="saving" @click="renaming=undefined">取消</button></div></div><fieldset v-if="!readonly" :disabled="saving||loading" class="member-add"><label>加入方式<select v-model="mode"><option value="new">新增项目成员</option><option value="existing">选择已有成员</option></select></label><label v-if="mode==='new'">成员姓名<input v-model="name" maxlength="100" placeholder="输入姓名后加入项目" @keydown.enter.prevent="add"/></label><label v-else>已有成员<select v-model="existing"><option value="" disabled>请选择成员</option><option v-for="member in choices" :key="member.id" :value="member.id">{{member.name}} · {{member.id.slice(0,8)}}</option></select></label><button type="button" class="button subtle small" :disabled="saving||loading||(mode==='new'?!name.trim():!existing)" @click="add">{{saving?'正在加入…':'加入项目'}}</button></fieldset></section></template>
<style scoped>.project-members{min-width:0}.project-member-list{padding:0;margin:12px 0 18px;list-style:none}.project-member-list li{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #e4eaf2}.project-member-list small{display:block;font-size:10px;color:#71849d;margin-top:4px;overflow-wrap:anywhere}.member-rename{padding:12px;background:#f8faff;border:1px solid #dfe6ef;border-radius:4px;margin:12px 0}.member-rename label{margin-bottom:4px}.member-add{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end}.member-add label{flex:1;min-width:160px;margin:0}.member-add button{margin-bottom:2px}.member-feedback{padding:9px 12px;background:#edf7f1;border:1px solid #cce5d6;border-radius:4px;color:#317452;font-size:12px;line-height:1.7}</style>
